"use strict";(self.webpackChunk_iehr_web=self.webpackChunk_iehr_web||[]).push([[2909],{7444:(e,s,t)=>{t.r(s),t.d(s,{assets:()=>c,contentTitle:()=>a,default:()=>u,frontMatter:()=>o,metadata:()=>n,toc:()=>l});const n=JSON.parse('{"id":"policies/Technical-Safeguards-Access-Control-Policy","title":"Technical Safeguards- Access Control Policy","description":"ScopeiEHR company and workforce.","source":"@site/docs/policies/Technical-Safeguards-Access-Control-Policy.md","sourceDirName":"policies","slug":"/policies/Technical-Safeguards-Access-Control-Policy","permalink":"/docs/policies/Technical-Safeguards-Access-Control-Policy","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{}}');var i=t(4848),r=t(8453);const o={},a="Technical Safeguards- Access Control Policy",c={},l=[{value:"ScopeiEHR company and workforce.",id:"scopeiehr-company-and-workforce",level:2},{value:"PurposeThe purpose of the Information Access Control Policy is to ensure that all members of the workforce have access to the systems and information appropriate to their job functions, and to ensure that inappropriate access is prevented under the HIPAA Security Policy- Security Standards for the Protection of Electronic Protected Health Information (ePHI).  iEHR is committed to following all applicable laws, regulations and policies. This Policy pertains to the unique user identification and password, emergency access, automatic logoff, encryption and decryption, firewall, and remote and wireless access procedures that will apply to electronic information systems that maintain ePHI.",id:"purposethe-purpose-of-the-information-access-control-policy-is-to-ensure-that-all-members-of-the-workforce-have-access-to-the-systems-and-information-appropriate-to-their-job-functions-and-to-ensure-that-inappropriate-access-is-prevented-under-the-hipaa-security-policy--security-standards-for-the-protection-of-electronic-protected-health-information-ephi--iehr-is-committed-to-following-all-applicable-laws-regulations-and-policies-this-policy-pertains-to-the-unique-user-identification-and-password-emergency-access-automatic-logoff-encryption-and-decryption-firewall-and-remote-and-wireless-access-procedures-that-will-apply-to-electronic-information-systems-that-maintain-ephi",level:2},{value:"Policy",id:"policy",level:2}];function d(e){const s={h1:"h1",h2:"h2",header:"header",li:"li",ol:"ol",p:"p",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(s.header,{children:(0,i.jsx)(s.h1,{id:"technical-safeguards--access-control-policy",children:"Technical Safeguards- Access Control Policy"})}),"\n",(0,i.jsx)(s.h2,{id:"scopeiehr-company-and-workforce",children:"ScopeiEHR company and workforce."}),"\n",(0,i.jsx)(s.h2,{id:"purposethe-purpose-of-the-information-access-control-policy-is-to-ensure-that-all-members-of-the-workforce-have-access-to-the-systems-and-information-appropriate-to-their-job-functions-and-to-ensure-that-inappropriate-access-is-prevented-under-the-hipaa-security-policy--security-standards-for-the-protection-of-electronic-protected-health-information-ephi--iehr-is-committed-to-following-all-applicable-laws-regulations-and-policies-this-policy-pertains-to-the-unique-user-identification-and-password-emergency-access-automatic-logoff-encryption-and-decryption-firewall-and-remote-and-wireless-access-procedures-that-will-apply-to-electronic-information-systems-that-maintain-ephi",children:"PurposeThe purpose of the Information Access Control Policy is to ensure that all members of the workforce have access to the systems and information appropriate to their job functions, and to ensure that inappropriate access is prevented under the HIPAA Security Policy- Security Standards for the Protection of Electronic Protected Health Information (ePHI).  iEHR is committed to following all applicable laws, regulations and policies. This Policy pertains to the unique user identification and password, emergency access, automatic logoff, encryption and decryption, firewall, and remote and wireless access procedures that will apply to electronic information systems that maintain ePHI."}),"\n",(0,i.jsx)(s.p,{children:"Authoritative Reference: The Health Insurance Portability and Accountability Act (HIPAA) of 1996 (P.L.104-191) HIPAA Security Rule [HIPAA Technical Safeguards] [see \xa7164.312(a)(1) & (2)]"}),"\n",(0,i.jsx)(s.h2,{id:"policy",children:"Policy"}),"\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsxs)(s.li,{children:["\n",(0,i.jsx)(s.p,{children:"Unique User Identification and Password"}),"\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"Any user that requires access to any network, system, or application that accesses, transmits, receives, or stores ePHI, must be provided with a unique username."}),"\n",(0,i.jsx)(s.li,{children:"When requesting access to any network, system, or application that accesses, transmits, receives, or stores ePHI, a user must supply his or her previously assigned unique username in conjunction with a secure password to gain access."}),"\n",(0,i.jsxs)(s.li,{children:["Each user\u2019s password should meet the minimum requirements as outlined below:","\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"Must be a minimum of eight characters in length."}),"\n",(0,i.jsx)(s.li,{children:"Must contain a unique character."}),"\n",(0,i.jsx)(s.li,{children:"Must contain a number."}),"\n",(0,i.jsx)(s.li,{children:"May not contain your user-name or any part of your full name"}),"\n",(0,i.jsx)(s.li,{children:"Passwords must not include easily guessed information such as personal information, names, pets, birth dates, etc."}),"\n",(0,i.jsxs)(s.li,{children:["If a system does not support the minimum structure and complexity as detailed in the previous guidelines, one of the following procedures must be implemented:","\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"The password assigned must be adequately complex to ensure that it is not easily guessed and the complexity of the chosen alternative must be defined and documented."}),"\n",(0,i.jsx)(s.li,{children:"The legacy system must be upgraded to support the requirements as soon as administratively possible."}),"\n",(0,i.jsx)(s.li,{children:"All ePHI must be removed and relocated to a system that supports the foregoing security password structure."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(s.li,{children:"Users must not allow another user to use their unique username or password."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(s.li,{children:"Users must ensure that their username and password is not documented, written, or otherwise exposed in an insecure manner."}),"\n",(0,i.jsx)(s.li,{children:"Each user must ensure that their assigned username is appropriately protected and only used for legitimate access to networks, systems, or applications."}),"\n",(0,i.jsx)(s.li,{children:"If a user believes their username or password has been comprised, they must report that security incident to their manager, who will contact the appropriate HIPAA Officer."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(s.li,{children:["\n",(0,i.jsx)(s.p,{children:"Emergency Access"}),"\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsxs)(s.li,{children:["The HIPAA Security Rule requires Covered Entities to establish procedures to allow access to ePHI during an emergency. During an emergency or disaster, covered entities must remember that protecting ePHI is of utmost importance. Emergency procedures may be very different from standard operating procedures, but they are necessary because the normal methods for obtaining access may fail. Emergencies include, but are not limited to, the following:","\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"Natural disasters \u2013 Floods, earthquakes, tornadoes, tsunamis, hurricanes, etc."}),"\n",(0,i.jsx)(s.li,{children:"Man-made disasters \u2013 Hacking attacks, thefts, vandalism, terrorist attacks, etc."}),"\n",(0,i.jsx)(s.li,{children:"Unforeseen disasters \u2013 Power outages, internal failures, etc."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(s.li,{children:"To ensure that access to critical ePHI is maintained during an emergency situation, each Department must establish and implement procedures to ensure that access to a system that contains ePHI and is used to provide treatment to an individual is made available to any caregiver, if the denial or strict access to that ePHI could inhibit or negatively affect an individual\u2019s care."}),"\n",(0,i.jsx)(s.li,{children:"ePHI repositories that do not affect an individual\u2019s care are not subject to the foregoing emergency access requirement."}),"\n",(0,i.jsxs)(s.li,{children:["When developing this policy and procedure, a covered entity should:","\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"Determine the type of situation that may require emergency access to ePHI."}),"\n",(0,i.jsx)(s.li,{children:"Determine who will need access to ePHI in case of an emergency"}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(s.li,{children:["In the case of emergency, a computer account may be temporarily shared with another individual. The requirements for emergency access sharing are:","\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"There must be a true emergency."}),"\n",(0,i.jsx)(s.li,{children:"The sharing must be temporary."}),"\n",(0,i.jsx)(s.li,{children:"The emergency incident must be reported to the managing authority of the computer account being shared."}),"\n",(0,i.jsx)(s.li,{children:"In no case should this emergency access sharing exceed 30 days."}),"\n",(0,i.jsx)(s.li,{children:"The Emergency access procedure must be used in case a terminated employee\u2019s computer account must be maintained for business reasons. Unless the Emergency Access procedure is implemented, all terminated employee computer accounts will be deleted immediately upon notification of the termination to all relevant parties."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(s.li,{children:"Emergency accounts have been created for accessing ePHI for continuing care.  These are unique usernames and passwords that can be tracked easily.  They should not be used unless there is a true emergency."}),"\n",(0,i.jsx)(s.li,{children:"Servers with ePHI are maintained off-site in order to reduce potential damage during a disaster at the facility."}),"\n",(0,i.jsx)(s.li,{children:"Critical personnel have been issued emergency response cards for access to the facilities in the event of an emergency or disaster."}),"\n",(0,i.jsxs)(s.li,{children:["In the event of power outage, a backup generator will be utilized.","\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"In the event the backup generator doesn\u2019t work, remote access will be utilized by the designated personnel.  Information will be printed or transmitted via phone (cell, sat) for patient care."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(s.li,{children:"If facility is under a pre-evacuation, print only necessary documents to maintain proper care for patients."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(s.li,{children:["\n",(0,i.jsx)(s.p,{children:"Automatic Logoff"}),"\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"Servers, workstations, or other computer systems located in open, common, or otherwise unsecure areas, that access, transmit, receive, or store ePHI, or that have been classified as high risk must employ inactivity timers or automatic logoff mechanisms. These systems must terminate a user session after a maximum of 15 minutes of inactivity."}),"\n",(0,i.jsx)(s.li,{children:"Applications and databases using ePHI, such as electronic claims records, must employ inactivity timers or automatic session logoff mechanisms. These application sessions must automatically terminate after a maximum of 30 minutes of inactivity."}),"\n",(0,i.jsx)(s.li,{children:"Servers, workstations, or other computer systems that access, transmit, receive, or store ePHI, and are located in locked or secure environments need not implement inactivity timers or automatic logoff mechanisms."}),"\n",(0,i.jsxs)(s.li,{children:["If a system that otherwise would require the use of an inactivity timer or automatic logoff mechanism does not support an inactivity timer or automatic logoff mechanism, one of the following procedures must be implemented:","\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"The system must be upgraded or moved to support the required inactivity timer or automatic logoff mechanism."}),"\n",(0,i.jsx)(s.li,{children:"The system must be moved into a secure environment."}),"\n",(0,i.jsx)(s.li,{children:"All ePHI must be removed and relocated to a system that supports the required inactivity timer or automatic logoff mechanism."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(s.li,{children:"When leaving a server, workstation, or other computer system unattended, users must lock or activate the system\u2019s automatic logoff mechanism (e.g. CTRL+ALT+DELETE and Lock Computer) or logout of all applications and database systems containing ePHI."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(s.li,{children:["\n",(0,i.jsx)(s.p,{children:"Encryption and Decryption"}),"\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"Encryption of ePHI as an access control mechanism is not required unless the custodian of said ePHI deems the data to be highly critical or sensitive. Encryption of ePHI is required in some instances as a transmission control and integrity mechanism."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(s.li,{children:["\n",(0,i.jsx)(s.p,{children:"Firewall Use"}),"\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"All networks housing ePHI repositories must be appropriately secured. To ensure that all networks that contain ePHI-based systems and applications are appropriately secured, each connection to outside the network must follow the steps outlined below. Networks containing ePHI-based systems and applications must implement perimeter security and access control with a firewall."}),"\n",(0,i.jsxs)(s.li,{children:["Firewalls must be configured to support the following minimum requirements:","\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"Limit network access to only authorized iEHR users and entities."}),"\n",(0,i.jsx)(s.li,{children:"Limit network access to only legitimate or established connections. An established connection is return traffic in response to an application request submitted from within the secure network."}),"\n",(0,i.jsx)(s.li,{children:"Console and other management ports must be appropriately secured or disabled."}),"\n",(0,i.jsx)(s.li,{children:"Implement mechanism to log failed access attempts."}),"\n",(0,i.jsx)(s.li,{children:"Must be located in a physically secure environment."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(s.li,{children:"iEHR must document its configuration of firewalls used to protect networks containing ePHI-based systems and applications. This documentation should include a configuration plan that outlines and explains the firewall rules."}),"\n",(0,i.jsx)(s.li,{children:"The configuration of firewalls used to protect networks containing ePHI-based systems and applications must be submitted to and approved by the Information Security Officer."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(s.li,{children:["\n",(0,i.jsx)(s.p,{children:"Remote Access"}),"\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"Dial-up connections (if allowed), directly into secure networks are considered to be secure connections and do not require a VPN connection. This implementation of secure remote access extends the secure network to the remote user using a secure PSTN (Public Switched Telephone Network) connection."}),"\n",(0,i.jsx)(s.li,{children:"Authentication and encryption mechanisms are required for all remote access sessions to networks containing ePHI via an ISP (Internet Service Provider) or dial-up connection. Examples of such mechanisms include VPN clients, authenticated SSL web sessions, and secured Citrix client access."}),"\n",(0,i.jsxs)(s.li,{children:["The following security measures must be implemented for any remote access connection into a secure network containing ePHI:","\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"Mechanisms to bypass authorized remote access mechanisms are strictly prohibited. For example, remote control software and applications, such as GoToMyPC.com, are not permitted."}),"\n",(0,i.jsx)(s.li,{children:"Remote access workstations must employ a virus detection and protection mechanism."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(s.li,{children:"Users of remote workstations must comply with HIPAA Security Policy \u2013 Workstation Acceptable Use Policy."}),"\n",(0,i.jsx)(s.li,{children:"All encryption mechanisms implemented to comply with this policy must support a minimum of, but not limited to, 128-bit encryption."}),"\n",(0,i.jsx)(s.li,{children:"Any user requesting remote access to a secure network containing ePHI-based systems and applications must be approved by the Security Officer to ensure that the remote workstation device being used by said user meets the security measures detailed in HIPAA Security Policy -- Server, Desktop, and Wireless Computer System Security. The owner of the secure network (IS or managing department) must ensure that the previous requirement has been satisfied before access is granted."}),"\n",(0,i.jsx)(s.li,{children:"iEHR must ensure that remote workstations and mobile devices used by their users to remotely access secure networks containing ePHI-based systems and applications continue to meet the security measures detailed in HIPAA Security Policy -- Server, Desktop, and Wireless Computer System Security."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(s.li,{children:["\n",(0,i.jsx)(s.p,{children:"Wireless Access"}),"\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsxs)(s.li,{children:["\n",(0,i.jsx)(s.p,{children:"To ensure that all networks that contain ePHI based systems and applications are appropriately secured, iEHR must follow the wireless access policies and procedures outlined below."}),"\n"]}),"\n",(0,i.jsxs)(s.li,{children:["\n",(0,i.jsx)(s.p,{children:"Wireless access to networks containing ePHI-based systems and applications is permitted so long as the following security measures have been implemented:"}),"\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"Encryption must be enabled."}),"\n",(0,i.jsx)(s.li,{children:"MAC-based or User ID/Password authentication must be enabled. MAC-based (Media Access Control) authentication is based on a permitted list of hardware addresses that can access the wireless network. MAC addresses are hard coded on each network interface card and typically cannot be changed."}),"\n",(0,i.jsx)(s.li,{children:"All console and other management interfaces have been appropriately secured or disabled."}),"\n",(0,i.jsx)(s.li,{children:"Unmanaged, ad-hoc, or rogue wireless access points ARE NOT PERMITTED on any secure network containing ePHI-based systems and applications."}),"\n",(0,i.jsx)(s.li,{children:"All wireless LANs do not utilize standard 2.4GHz, 5.0GHz or microwave radio frequencies. Wireless LANs and devices may utilize infrared frequencies and may not support the typical wireless LAN encryption and security mechanisms. For instance, the use of infrared ports on PDAs, laptops, and printers to transmit ePHI may not allow encryption of that data stream. It has been determined that this is low risk because this implementation of infrared is very short distance and low power."}),"\n",(0,i.jsx)(s.li,{children:"All encryption mechanisms implemented to comply with this policy must support a minimum of, but not limited to, 128-bit encryption."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(s.li,{children:["\n",(0,i.jsx)(s.p,{children:"Any user requesting access to a secure wireless network containing ePHI-based systems and applications must ensure that the wireless device being used by said user meets the security measures detailed in HIPAA Security Policy -- Server, Desktop, and Wireless Computer System Security. The owner (managing entity) of the secure wireless network must ensure that the previous requirement has been satisfied before access is granted."}),"\n"]}),"\n",(0,i.jsxs)(s.li,{children:["\n",(0,i.jsx)(s.p,{children:"iEHR must establish a formal, documented procedure to ensure that wireless devices used by their users to access secure networks containing EPHI-based systems and applications continue to meet the security measures detailed in HIPAA Security Policy -- Server, Desktop, and Wireless Computer System Security."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(s.p,{children:["**Violations",":Any"," individual, found to have violated this policy, may be subject to disciplinary action up to and including termination of employment."]}),"\n"]}),"\n"]})]})}function u(e={}){const{wrapper:s}={...(0,r.R)(),...e.components};return s?(0,i.jsx)(s,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453:(e,s,t)=>{t.d(s,{R:()=>o,x:()=>a});var n=t(6540);const i={},r=n.createContext(i);function o(e){const s=n.useContext(r);return n.useMemo((function(){return"function"==typeof e?e(s):{...s,...e}}),[s,e])}function a(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),n.createElement(r.Provider,{value:s},e.children)}}}]);